        return function(ctx)
            local M = {}

            local qualities = {
                "Broken",
                "Refined",
                "Pristine",
                "Divine",
                "Artifact",
                "Transcendent",
            }

            local qualityRank = {
                Broken = 1,
                Refined = 2,
                Pristine = 3,
                Divine = 4,
                Artifact = 5,
                Transcendent = 6,
            }

            local optionMap = {}
            local optionMeta = {}
            local dropdown = nil
            local busy = false
            local attempts = 0
            local lastStatusText = nil

            local cachedResultLabel = nil
            local cachedReforgeRoot = nil
            local lastLabelScan = 0

            local function save()
                if type(ctx.Save) == "function" then
                    pcall(ctx.Save)
                end
            end

            local function notify(title, content, duration)
                if ctx.Notifier and type(ctx.Notifier.new) == "function" then
                    pcall(function()
                        ctx.Notifier.new({
                            Title = title,
                            Content = content,
                            Duration = duration or 4,
                        })
                    end)
                end
            end

            local function canonicalQuality(value)
                local s = string.lower(tostring(value or ""))

                for _, quality in ipairs(qualities) do
                    if string.find(s, string.lower(quality), 1, true) then
                        return quality
                    end
                end

                return nil
            end

            local function normalizePercent(value)
                local n = tonumber(value)
                if not n then
                    return nil
                end

                if n >= -20.05 and n <= 18.05 then
                    return n
                end

                return nil
            end

            local function parsePercent(value)
                local s = tostring(value or "")
                local numberText = string.match(
                    s,
                    "([%+%-]?%d+%.?%d*)%s*%%"
                )

                if numberText then
                    return normalizePercent(tonumber(numberText))
                end

                return nil
            end

            local function inferQuality(percent)
                local p = normalizePercent(percent)
                if p == nil then
                    return "Unknown"
                end

                if p >= 15 then
                    return "Transcendent"
                elseif p >= 10 then
                    return "Artifact"
                elseif p >= 5 then
                    return "Divine"
                elseif p >= 0 then
                    return "Pristine"
                elseif p >= -10 then
                    return "Refined"
                else
                    return "Broken"
                end
            end

            local function getInventory()
                return ctx.LocalPlayer
                    and ctx.LocalPlayer:FindFirstChild("Inventory")
                    or nil
            end

            local function readItemState(item, allowUI)
                if not item or not item.Parent then
                    return nil, nil
                end

                local qAttr = item:GetAttribute("Quality")
                if qAttr ~= nil and type(qAttr) == "number" then
                    local percent = tonumber(qAttr) or 0
                    local quality = inferQuality(percent)
                    return quality, percent
                end

                if allowUI ~= false then
                    local playerGui = ctx.LocalPlayer:FindFirstChildOfClass("PlayerGui") or ctx.LocalPlayer:FindFirstChild("PlayerGui")
                    local inRange = playerGui and playerGui:FindFirstChild("Main") and playerGui.Main:FindFirstChild("InRangeFrames")
                    local reforgeUI = inRange and inRange:FindFirstChild("Reforge")
                    if reforgeUI and reforgeUI:FindFirstChild("CurrentQuality") then
                        local txt = tostring(reforgeUI.CurrentQuality.Text or "")
                        if txt ~= "" and txt ~= "NONE" then
                            local quality = canonicalQuality(txt)
                            local rawPercent = parsePercent(txt)
                            local percent = normalizePercent(rawPercent)
                            if quality and percent ~= nil then
                                return quality, percent
                            end
                            if percent ~= nil then
                                return inferQuality(percent), percent
                            end
                        end
                    end
                end

                return "Pristine", 0
            end

            local function doReforgeRoll(item)
                -- 1. Sync in-game Reforge UI
                pcall(function()
                    local playerGui = ctx.LocalPlayer:FindFirstChildOfClass("PlayerGui") or ctx.LocalPlayer:FindFirstChild("PlayerGui")
                    local inRange = playerGui and playerGui:FindFirstChild("Main") and playerGui.Main:FindFirstChild("InRangeFrames")
                    local reforgeUI = inRange and inRange:FindFirstChild("Reforge")
                    if reforgeUI then
                        local reforgeBtn = reforgeUI:FindFirstChild("Reforge")
                        if reforgeBtn and reforgeBtn:FindFirstChild("Item") then
                            reforgeBtn.Item.Value = item
                        end

                        -- Virtual Mouse Click on in-game Reforge Button
                        if reforgeBtn and reforgeBtn:IsA("GuiButton") and reforgeBtn.Visible then
                            local VirtualInputManager = game:GetService("VirtualInputManager")
                            local pos = reforgeBtn.AbsolutePosition
                            local size = reforgeBtn.AbsoluteSize
                            if pos.X > 0 and pos.Y > 0 then
                                VirtualInputManager:SendMouseButtonEvent(pos.X + size.X / 2, pos.Y + size.Y / 2, 0, true, game, 0)
                                task.wait(0.02)
                                VirtualInputManager:SendMouseButtonEvent(pos.X + size.X / 2, pos.Y + size.Y / 2, 0, false, game, 0)
                            end
                        end
                    end
                end)

                -- 2. Reliable InvokeServer
                local remotes = ctx.ReplicatedStorage:FindFirstChild("Remotes")
                local upgradeRemote = remotes and remotes:FindFirstChild("Upgrade")
                local res = nil
                if upgradeRemote and upgradeRemote:IsA("RemoteFunction") then
                    local ok, result = pcall(function()
                        return upgradeRemote:InvokeServer("Reforge", item)
                    end)
                    if ok then
                        res = result
                    end
                end

                -- 3. Update in-game Reforge text
                local finalQ = res or item:GetAttribute("Quality")
                if finalQ and type(finalQ) == "number" then
                    local qName = inferQuality(finalQ)
                    pcall(function()
                        local playerGui = ctx.LocalPlayer:FindFirstChildOfClass("PlayerGui") or ctx.LocalPlayer:FindFirstChild("PlayerGui")
                        local reforgeUI = playerGui and playerGui.Main.InRangeFrames.Reforge
                        if reforgeUI and reforgeUI:FindFirstChild("CurrentQuality") then
                            reforgeUI.CurrentQuality.Text = string.format("%s (%+.2f%%)", qName, finalQ)
                        end
                    end)
                end

                return res
            end

            local function goalState(item)
                local quality, percent = readItemState(item, true)
                if not quality or percent == nil then
                    return false, quality, percent
                end

                percent = normalizePercent(percent) or percent

                local currentRank = qualityRank[quality] or 3
                local targetRank = qualityRank[ctx.Config.ReforgeTargetQuality] or 4
                local minPercent = tonumber(ctx.Config.ReforgeMinPercent) or 5
                local orHigher = ctx.Config.ReforgeOrHigher ~= false

                local isMet = false
                if orHigher then
                    if currentRank > targetRank then
                        isMet = true
                    elseif currentRank == targetRank and percent >= minPercent then
                        isMet = true
                    end
                else
                    if currentRank == targetRank and percent >= minPercent then
                        isMet = true
                    end
                end

                return isMet, quality, percent
            end

            local function identityHint(item)
                if not item then
                    return nil
                end

                local attrs = item:GetAttributes()
                local keys = {
                    "UUID", "Uid", "UID",
                    "UniqueId", "UniqueID",
                    "ItemId", "ItemID",
                    "InventoryId", "InventoryID",
                }

                for _, key in ipairs(keys) do
                    local value = attrs[key]
                    if value ~= nil then
                        local s = tostring(value)
                        if s ~= "" then
                            if #s > 8 then
                                s = string.sub(s, -8)
                            end
                            return s
                        end
                    end
                end

                return nil
            end

            function M.BuildOptions()
                local inv = getInventory()
                local values = {}
                local counts = {}
                local ordinals = {}

                optionMap = {}
                optionMeta = {}

                if not inv then
                    return { "Select Item" }
                end

                local children = inv:GetChildren()

                for _, item in ipairs(children) do
                    counts[item.Name] = (counts[item.Name] or 0) + 1
                end

                for index, item in ipairs(children) do
                    local baseName = tostring(item.Name)
                    ordinals[baseName] = (ordinals[baseName] or 0) + 1

                    local ordinal = ordinals[baseName]
                    local quality, percent = readItemState(item, false)

                    local buffText = quality or "Unknown"
                    if percent ~= nil then
                        buffText = buffText
                            .. string.format(" %+.2f%%", percent)
                    end

                    local suffix = ""
                    if (counts[baseName] or 0) > 1 then
                        suffix = " #" .. tostring(ordinal)
                    end

                    local hint = identityHint(item)
                    if hint then
                        suffix = suffix .. " [" .. hint .. "]"
                    end

                    local label = baseName
                        .. " | "
                        .. buffText
                        .. suffix

                    if optionMap[label] then
                        label = label .. " @" .. tostring(index)
                    end

                    optionMap[label] = item
                    optionMeta[label] = {
                        Name = baseName,
                        Ordinal = ordinal,
                    }

                    table.insert(values, label)
                end

                table.sort(values)

                if #values == 0 then
                    table.insert(values, "Select Item")
                end

                return values
            end

            local function findItem(selection)
                local value = tostring(selection or "")

                if value == "" or value == "Select Item" then
                    return nil
                end

                local mapped = optionMap[value]
                if mapped and mapped.Parent then
                    return mapped
                end

                -- Rebuild once if Inventory changed.
                M.BuildOptions()

                mapped = optionMap[value]
                if mapped and mapped.Parent then
                    return mapped
                end

                local inv = getInventory()
                local fallbackName =
                    tostring(ctx.Config.ReforgeItemName or "")

                if inv and fallbackName ~= "" then
                    for _, item in ipairs(inv:GetChildren()) do
                        if item.Name == fallbackName then
                            return item
                        end
                    end
                end

                return nil
            end

            local function selectedItem()
                local selector =
                    tostring(ctx.Config.ReforgeItemSelector or "")

                if selector == "" then
                    selector = tostring(
                        ctx.Config.ReforgeItemName or ""
                    )
                end

                return findItem(selector)
            end

            local function statusText()
                local item = selectedItem()
                local selectedName =
                    item and item.Name
                    or tostring(ctx.Config.ReforgeItemName or "")

                if not item
                    and (selectedName == ""
                        or selectedName == "Select Item") then

                    return "Item: Not selected"
                        .. "\nCurrent: --"
                        .. "\nTarget: "
                        .. tostring(
                            ctx.Config.ReforgeTargetQuality
                                or "Divine"
                        )
                        .. " / "
                        .. string.format(
                            "%+.2f%%",
                            tonumber(
                                ctx.Config.ReforgeMinPercent
                            ) or 0
                        )
                        .. "\nStatus: Waiting for item"
                end

                if not item then
                    return "Item: " .. selectedName
                        .. "\nCurrent: Item not found"
                        .. "\nTarget: "
                        .. tostring(
                            ctx.Config.ReforgeTargetQuality
                                or "Divine"
                        )
                        .. " / "
                        .. string.format(
                            "%+.2f%%",
                            tonumber(
                                ctx.Config.ReforgeMinPercent
                            ) or 0
                        )
                        .. "\nStatus: Waiting for item"
                end

                local goalMet, quality, percent =
                    goalState(item)

                local currentText = quality or "Unknown"

                if percent ~= nil then
                    currentText = currentText
                        .. string.format(
                            " (%+.2f%%)",
                            percent
                        )
                end

                local targetText =
                    tostring(
                        ctx.Config.ReforgeTargetQuality
                            or "Divine"
                    )
                    .. " / "
                    .. string.format(
                        "%+.2f%%",
                        tonumber(ctx.Config.ReforgeMinPercent) or 0
                    )
                    .. (ctx.Config.ReforgeOrHigher ~= false and " (or Higher)" or "")

                local status

                if goalMet then
                    status = "Goal Reached ✓"
                elseif ctx.Config.AutoReforge and busy then
                    status = "Reforging..."
                elseif ctx.Config.AutoReforge then
                    status = "Starting..."
                else
                    status = "Ready"
                end

                return "Item: " .. selectedName
                    .. "\nCurrent: " .. currentText
                    .. "\nTarget: " .. targetText
                    .. "\nAttempts: "
                    .. tostring(attempts)
                    .. " / "
                    .. tostring(
                        ctx.Config.ReforgeMaxAttempts or 100
                    )
                    .. "\nStatus: " .. status
            end

            function M.UpdateStatus()
                if not ctx.Paragraph
                    or type(ctx.Paragraph.SetContent)
                        ~= "function" then
                    return
                end

                local ok, content = pcall(statusText)

                if not ok or type(content) ~= "string" then
                    return
                end

                if content == lastStatusText then
                    return
                end

                lastStatusText = content

                pcall(function()
                    ctx.Paragraph:SetContent(content)
                end)
            end

            function M.SetDropdown(obj)
                dropdown = obj
            end

            function M.Select(selected)
                local value =
                    type(selected) == "table"
                    and (selected[1] or next(selected))
                    or selected

                value = tostring(value or "")

                ctx.Config.ReforgeItemSelector = value

                local item = findItem(value)
                ctx.Config.ReforgeItemName =
                    item and item.Name or ""

                cachedResultLabel = nil
                save()
                M.UpdateStatus()
            end

            function M.SetQuality(selected)
                local value =
                    type(selected) == "table"
                    and (selected[1] or next(selected))
                    or selected

                ctx.Config.ReforgeTargetQuality =
                    tostring(value or "Divine")

                save()
                M.UpdateStatus()
            end

            function M.SetMinPercent(value)
                ctx.Config.ReforgeMinPercent =
                    tonumber(value) or 5

                save()
                M.UpdateStatus()
            end

            function M.SetMaxAttempts(value)
                ctx.Config.ReforgeMaxAttempts =
                    math.floor(tonumber(value) or 100)

                save()
                M.UpdateStatus()
            end

            function M.RefreshItems()
                local values = M.BuildOptions()

                if dropdown
                    and type(dropdown.SetValues)
                        == "function" then
                    pcall(function()
                        dropdown:SetValues(values)
                    end)
                end

                M.UpdateStatus()

                notify(
                    "Auto Reforge",
                    "Reforge item list refreshed.",
                    3
                )
            end

            function M.Inspect()
                local item = selectedItem()

                if not item then
                    notify(
                        "Auto Reforge",
                        "No item selected.",
                        3
                    )
                    return
                end

                local quality, percent =
                    readItemState(item, true)

                local textValue = quality or "Unknown"

                if percent ~= nil then
                    textValue = textValue
                        .. string.format(
                            " (%+.2f%%)",
                            percent
                        )
                end

                notify(
                    "Reforge State",
                    textValue,
                    5
                )

                M.UpdateStatus()
            end

            function M.RollOnce()
                local item = selectedItem()
                if not item then
                    notify("Auto Reforge", "กรุณาเลือกไอเทมก่อนรี", 3)
                    return
                end

                doReforgeRoll(item)
                task.wait(0.2)
                M.UpdateStatus()
                V17.UpdateReforgeStatus()
                notify("Auto Reforge", "รีไอเทม 1 ครั้งเรียบร้อย!", 3)
            end

            local function runWorker()
                if busy or not ctx.Config.AutoReforge then
                    return
                end

                busy = true
                attempts = 0
                M.UpdateStatus()

                task.spawn(function()
                    local maxAttempts = math.clamp(
                        tonumber(
                            ctx.Config.ReforgeMaxAttempts
                        ) or 100,
                        1,
                        500
                    )

                    while ctx.Config.AutoReforge
                        and attempts < maxAttempts do

                        local item = selectedItem()

                        if not item or not item.Parent then
                            break
                        end

                        local goalMet, quality, percent =
                            goalState(item)

                        if goalMet then
                            notify("Auto Reforge", string.format("เป้าหมายสำเร็จ! ได้ %s (%+.2f%%)", quality or "Quality", percent or 0), 4)
                            break
                        end

                        -- Check gold
                        local pstats = ctx.LocalPlayer:FindFirstChild("PlayerStats")
                        local gold = pstats and pstats:FindFirstChild("Gold") and tonumber(pstats.Gold.Value) or 0
                        if gold < 50 then
                            notify("Auto Reforge", "เงินไม่เพียงพอสำหรับการรี!", 4)
                            break
                        end

                        attempts = attempts + 1
                        M.UpdateStatus()

                        doReforgeRoll(item)

                        local rollDelay = ctx.Config.ReforgeFastMode and 0.05 or 0.25
                        task.wait(rollDelay)

                        M.UpdateStatus()

                        local afterGoalMet, afterQuality, afterPercent =
                            goalState(item)

                        if afterGoalMet then
                            notify("Auto Reforge", string.format("เป้าหมายสำเร็จ! ได้ %s (%+.2f%%)", afterQuality or "Quality", afterPercent or 0), 4)
                            break
                        end
                    end

                    ctx.Config.AutoReforge = false
                    busy = false
                    save()
                    M.UpdateStatus()
                end)
            end

            function M.Toggle(value)
                ctx.Config.AutoReforge =
                    value == true

                save()
                M.UpdateStatus()

                if not value then
                    return
                end

                local item = selectedItem()

                if not item then
                    ctx.Config.AutoReforge = false
                    save()

                    notify(
                        "Auto Reforge",
                        "Select an inventory item first.",
                        4
                    )

                    M.UpdateStatus()
                    return
                end

                runWorker()
            end

            function M.StartSaved()
                if ctx.Config.AutoReforge then
                    task.defer(function()
                        task.wait(1.5)
                        runWorker()
                    end)
                end
            end

            function M.StartStatusLoop()
                task.spawn(function()
                    while true do
                        task.wait(
                            ctx.Config.AutoReforge
                            and 0.35
                            or 1.00
                        )
                        M.UpdateStatus()
                    end
                end)
            end

            M.Qualities = qualities

            return M
        end
